#!/usr/bin/env node
import { readFile } from 'node:fs/promises';

import { upsertTrustBriefPrComment } from '../lib/github/pr-comment.ts';

function usage() {
  return `ARC post PR comment

Usage:
  npm run arc:post-pr-comment -- --body <path> [--repo owner/repo] [--pr <number>]

Options:
  --body <path>       Markdown Trust Brief generated by arc:pr-check
  --repo <owner/repo> GitHub repository, defaults to GITHUB_REPOSITORY
  --pr <number>       Pull request number, defaults to GITHUB_EVENT_PATH pull_request.number
  --token <token>     GitHub token, defaults to GITHUB_TOKEN
  --api-url <url>     GitHub API URL, defaults to GITHUB_API_URL or https://api.github.com
  --help              Show this help
`;
}

function fail(message, details, code = 1) {
  console.error(`ARC post PR comment failed: ${message}`);
  if (details) console.error(details);
  process.exit(code);
}

function parseArgs(argv) {
  const options = { body: null, repo: process.env.GITHUB_REPOSITORY ?? null, pr: null, token: process.env.GITHUB_TOKEN ?? null, apiUrl: process.env.GITHUB_API_URL ?? 'https://api.github.com', help: false };
  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    const next = () => {
      index += 1;
      if (index >= argv.length || argv[index].startsWith('--')) fail(`${arg} requires a value.`, usage());
      return argv[index];
    };
    if (arg === '--help' || arg === '-h') options.help = true;
    else if (arg === '--body') options.body = next();
    else if (arg === '--repo') options.repo = next();
    else if (arg === '--pr') options.pr = Number(next());
    else if (arg === '--token') options.token = next();
    else if (arg === '--api-url') options.apiUrl = next();
    else fail(`Unknown option: ${arg}`, usage());
  }
  return options;
}

async function prNumberFromEventPath(eventPath) {
  if (!eventPath) return null;
  const event = JSON.parse(await readFile(eventPath, 'utf8'));
  const number = event?.pull_request?.number ?? event?.number;
  return Number.isInteger(number) && number > 0 ? number : null;
}

async function main() {
  const options = parseArgs(process.argv.slice(2));
  if (options.help) {
    console.log(usage());
    return;
  }
  if (!options.body) fail('Missing --body.', usage());
  if (!options.repo) fail('Missing repository. Pass --repo or set GITHUB_REPOSITORY.', usage());
  if (!options.token) fail('Missing GitHub token. Pass --token or set GITHUB_TOKEN.', usage());

  const prNumber = options.pr ?? await prNumberFromEventPath(process.env.GITHUB_EVENT_PATH);
  if (!prNumber) fail('Missing PR number. Pass --pr or run inside a pull_request event.', usage());

  const bodyMarkdown = await readFile(options.body, 'utf8');
  const result = await upsertTrustBriefPrComment({
    token: options.token,
    repository: options.repo,
    prNumber,
    bodyMarkdown,
    apiUrl: options.apiUrl,
  });

  console.log(`ARC Trust Brief PR comment ${result.action}: ${result.commentId}`);
}

main().catch((error) => {
  fail('Unexpected error.', error instanceof Error ? error.stack ?? error.message : String(error), 2);
});
